                                         when kp.id in (3, 5) then \'Asuransi Swasta\'
                                         when kp.id = 6 then \'Perjanjian\'
                                         when kp.id = 1 then \'Membayar Sendiri\'
                                         else null end) as golbayar,
                                         (case when kp.id = 2 then \'2.1\'
                                          when kp.id in (3, 5) then \'2.2\'
