        $pasienKeluarRI = 0;
        $pasienDirawatRI = 0;
        $pasienRawatJalan = 0;
        $pasienLab = 0;
        $pasienRad = 0;
        $pasienLain = 0;

        foreach ($data as $item) {
            $sama = false;
