    public function getEditDiagnosa(Request $request)
    {
        $filter = $request->all();


        $kddiagnosa = '';
        if (isset($filter['kdDiagnosa']) && $filter['kdDiagnosa'] != "" && $filter['kdDiagnosa'] != "undefined") {
            $kddiagnosa = ' AND mpr.id = ' . $filter['kdDiagnosa'];
        }

        $data = DB::select(DB::raw("
        SELECT mpr.id, mpr.golongansebabpenyakit, diagnosa_m.kddiagnosa, dbm.kddiagnosa as dbm_kddiagnosa, dbm.nodtd
FROM     mappingrlmorbiditas_m as mpr INNER JOIN
                  diagnosabantuan_m as dbm ON dbm.kddiagnosa = mpr.kddiagnosa INNER JOIN
				  diagnosa_m ON mpr.kddiagnosa = diagnosa_m.kddiagnosa
             $kddiagnosa

        "));
        $result = array(
            'data' => $data,
