    public function saveHasilEditDiagnosa(Request $request)
    {
        $r_NewMRLM = $request['mappingrlmorbiditas'];
        $r_NewDBM = $request['diagnosabantuan_m'];
        //  return($r_NewDBM); die();
        DB::beginTransaction();
        //##MappingRLMorbiditas##
        try {

            if ($r_NewMRLM['nodtd'] != 'undefined' && $r_NewMRLM['golongansebabpenyakit'] != 'undefined' && $r_NewMRLM['kddiagnosa'] != 'undefined') {
                $updateMRLM = EditDiagnosa::where('kddiagnosa', $r_NewMRLM['kddiagnosa'])
                    ->update(
                        [
                            'nodtd' => $r_NewMRLM['nodtd'],
                            'kddiagnosa' => $r_NewMRLM['kddiagnosa'],
                            'golongansebabpenyakit' => $r_NewMRLM['golongansebabpenyakit'],
                        ]
                    );
            }
            if ($r_NewDBM['nodtd'] != 'undefined') {
                // return($r_NewDBM['nodtd']); die();
                $updateDBM = EditNoDtd::where('kddiagnosa', $r_NewMRLM['kddiagnosa'])
                    ->update(
                        [
                            'nodtd' => $r_NewMRLM['nodtd'],
                        ]
                    );
            }
            // $dataDBM = EditNoDtd::where('nodtd',$r_NewDBM['nodtd'])->first();
            // $dataDBM->nodtd = $r_NewDBM['nodtd'];

            //  EditDiagnosa::where('id')->update(['nodtd'=>'nodtd', 'golongansebabpenyakit'=>'golongansebabpenyakit']);
            $transStatus = 'true';
        } catch (\Exception $e) {
            $transStatus = 'false';
        }




        if ($transStatus == 'true') {
            DB::commit();
            $transMessage = 'SUKSES';
            $result = array(
                'status' => 201,
                'message' => $transMessage,
                //    'dataDBM' => $dataDBM,
                //                'dataAPD' => $dataAPD,
                //                'dataRPP'=> $dataRPP,
                'as' => 'ramdanegie',
            );
        } else {
            $transMessage = "GAGAL";
            DB::rollBack();
            $result = array(
                'status' => 400,
                'message'  => $transMessage,
                //    'dataDBM' => $dataDBM,
                //                'dataAPD' => $dataAPD,
                //                'dataRPP'=> $dataRPP,
                'as' => 'ramdanegie',
            );
        }
        return $this->setStatusCode($result['status'])->respond($result, $transMessage);
    }

