    {
        $datad = \DB::table('diagnosabantuan_m as dbn')
            ->leftjoin('diagnosa_m as dm', 'dm.kddiagnosa', '=', 'dbn.kddiagnosa')
            ->leftjoin('diagnosadtd_m as ddtd', 'ddtd.nodtd', '=', 'dbn.nodtd')
            ->leftjoin('mappingrlmorbiditas_m as mpr', 'mpr.kddiagnosa', '=', 'dm.kddiagnosa')
            ->select('dbn.nodtd', 'mpr.golongansebabpenyakit as golongansebabpenyakit')
            ->wherein('dbn.nodtd', [
                '001', '002', '003', '004.9', '005', '007.0', '007.1', '008.1', '008.4', '011', '012', '013', '014', '015',
                '016', '019', '028', '029', '032.1', '035', '037', '043', '051', '057.0', '165.9', '166', '167', '169', '170'
            ])
            ->distinct()
            ->get();

