            $data = $data->whereIn('ru.id', [3, 4, 6, 7, 8, 9, 12, 13, 14, 17, 19, 20, 25, 26, 27, 31, 33, 70, 89, 97, 130, 132, 247, 248, 250, 253, 268, 319, 322, 446, 447, 448, 459, 456, 461, 543, 552, 564, 784, 788, 790, 792,569,786,796,787]);
