    public function getLaporanPengunjungPolriDetailverifcariselisih(Request $request)
    {

        $bulan = $request['bulan'];
        $tahun = $request['tahun'];        
        $data = DB::select(
                DB::raw("
                    SELECT distinct verifKSO_t.nocm, verifKSO_t.noregistrasi, verifKSO_t.instalasi, verifKSO_t.penjamin, verifKSO_t.penjaminkhusus, verifKSO_t.tglverif, verifKSO_t.tgldibagikan, tempverifKSO_t.instalasi AS instalasibaru, 
                    tempverifKSO_t.penjamin AS penjaminbaru, tempverifKSO_t.penjaminkhusus AS penjaminkhususbaru, departemen_m_1.namadepartemen AS namainstalasi, departemen_m.namadepartemen AS namainstalasilama
                    FROM verifKSO_t INNER JOIN
                    tempverifKSO_t ON verifKSO_t.noregistrasi = tempverifKSO_t.noregistrasi AND verifKSO_t.nocm = tempverifKSO_t.nocm INNER JOIN
                    departemen_m AS departemen_m_1 ON verifKSO_t.instalasi = departemen_m_1.id INNER JOIN
                    departemen_m ON tempverifKSO_t.instalasi = departemen_m.id
                    where verifKSO_t.statusenabled=1 and month(tglverif)=:bulan and year(tglverif)=:tahun and (verifKSO_t.instalasi <>  tempverifKSO_t.instalasi or verifKSO_t.penjamin <> tempverifKSO_t.penjamin or verifKSO_t.penjaminkhusus<>
                    tempverifKSO_t.penjaminkhusus)"),
                // where pp.strukresepfk=:strukresepfk"),
                array(
                    'bulan' => $bulan,
                    'tahun' => $tahun,
                )
            );
       
        $result = array(
                'data' => $data,
        );
        return $this->respond($result);
    }

