    public function getLaporanKunjunganPolriRadiologi(Request $request)
    {
        $tglAwal = $request['tglAwal'];
        $tglAkhir = $request['tglAkhir'];
        $idDept = $request['idDept'];
        $idRuangan2 = $request['idRuangan'];

        $paramRuangan = ' ';
        if (isset($idRuangan2) && $idRuangan2 != "" && $idRuangan2 != "undefined") {
            $paramRuangan = ' ru.id = ' . $idRuangan2;
        }
        $Ruangan = " ";
        if (isset($request['idRuangan']) && $request['idRuangan'] != "" && $request['idRuangan'] != "undefined") {
            $idRuangan = $request['idRuangan'];
            $Ruangan = "AND [ru].[id]= $idRuangan";
        }
        $paramDept = ' ';
        if (isset($idDept) && $idDept != "" && $idDept != "undefined") {
            $paramRuangan = ' and ru.objectdepartemenfk = ' . $idDept;
        }

        $data = DB::select(DB::raw("
        select idruangan, iddepartemen, namaruangan,
sum(baru) as jmlPasienBaru,
sum(lama) as jmlPasienLama,
sum(baru + lama) as jmlPasien,
sum(tracer) as jmlPasienTracer,
sum(nontracer) as jmlPasienNonTracer,
sum(konsul) as jmlPasienKonsul,
sum(tracer + nontracer + konsul) as jmlPasienKunjungan,
sum(bpjspol) as jmlPasienBpjsPol,
sum(bpjsnonpol) as jmlPasienBpjsNonPol,
sum(ptt) as jmlPasienPTT,
sum(umum) as jmlPasienUmum,
sum(tagihan) as jmlPasienTagihan,
sum(bpjspol + bpjsnonpol + ptt + umum + tagihan) as jmlPasienPembayaran,
sum(sendiri) as jmlPasienSendiri,
sum(rujukan) as jmlPasienRujukan,
sum(pasca) as jmlPasienPasca,
sum(sendiri + rujukan + pasca) as jmlPasienKedatangan,
sum(pulang) as jmlPulangPengunjungPulang,
sum(rawat) as jmlPulangPengunjungRawat,
sum(konsulplg) as jmlPulangPengunjungKonsul,
sum(rujuk) as jmlPulangPengunjungRujuk,
sum(batal) as jmlPulangPengunjungBatal,
sum(register) as jmlPulangPengunjungRegister,
sum(pulang + rawat + konsulplg + rujuk + batal + register) as jmlPulangPengunjung,
sum(pulangksl) as jmlPulangKonsulPulang,
sum(rawatksl) as jmlPulangKonsulRawat,
sum(konsulplgksl) as jmlPulangKonsulKonsul,
sum(rujukksl) as jmlPulangKonsulRujuk,
sum(batalksl) as jmlPulangKonsulBatal,
sum(registerksl) as jmlPulangKonsulRegister,
sum(pulangksl + rawatksl + konsulplgksl + rujukksl + batalksl + registerksl) as jmlPulangKonsul,
sum(pulangksl + pulang) as TotalPulang,
sum(rawatksl + rawat) as TotalRawat,
sum(konsulplgksl + konsulplg) as TotalKonsul,
sum(rujukksl + rujuk) as TotalRujuk,
sum(batalksl + batal) as TotalBatal,
sum(registerksl + register) as TotalRegister,
sum(pulang + rawat + konsulplg + rujuk + batal + register + pulangksl + rawatksl + konsulplgksl + rujukksl + batalksl + registerksl) as TotalAll
from(
select apd.tglregistrasi,ru.id as idruangan,pd.noregistrasi,apd.objectruanganasalfk, ps.namapasien,ru1.objectdepartemenfk as iddepartemen,
sum(case when apd.statuskunjungan = 'BARU' and apd.objectruanganasalfk is null then 1 else 0 end) as baru,
sum(case when apd.statuskunjungan = 'LAMA' and apd.objectruanganasalfk is null then 1 else 0 end) as lama,
sum(case when apd.statuskunjungan = 'BARU' and apd.objectruanganasalfk is null and apd.statuskunjungan = 'LAMA' then 0 else 0 end) as tracer,
sum(case when apd.objectruanganasalfk is null then 1 else 0 end) as nontracer,
sum(case when apd.objectruanganasalfk is not null then 1 else 0 end) as konsul,
sum(case when pd.objectrekananfk = 581368 then 1 else 0 end) as bpjspol,
sum(case when pd.objectrekananfk = 581367 or pd.objectrekananfk = 5906 then 1 else 0 end) as bpjsnonpol,
sum(case when pd.objectrekananfk = 581456 then 1 else 0 end) as ptt,
sum(case when pd.objectrekananfk = 0 then 1 else 0 end) as umum,
sum(case when pd.objectrekananfk not in (581368, 581367, 5906, 581456, 0) then 1 else 0 end) as tagihan,
sum(case when apd.objectasalrujukanfk in (5, 4) then 1 else 0 end) as sendiri,
sum(case when apd.objectasalrujukanfk in (1,2,3,6) then 1 else 0 end) as rujukan,
sum(case when apd.objectasalrujukanfk = 7 then 1 else 0 end) as pasca,
sum(case when apd.objectstatuspulangfk = 13 and apd.objectruanganasalfk is null then 1 else 0 end) as pulang,
sum(case when apd.objectstatuspulangfk = 15 and apd.objectruanganasalfk is null then 1 else 0 end) as rawat,
sum(case when apd.objectstatuspulangfk = 14 and apd.objectruanganasalfk is null then 1 else 0 end) as konsulplg,
sum(case when apd.objectstatuspulangfk = 16 and apd.objectruanganasalfk is null then 1 else 0 end) as rujuk,
sum(case when pd.statusenabled = 0 then 1 else 0 end) as batal,
sum(case when apd.objectstatuspulangfk not in (13,15,14,16) or apd.objectruanganasalfk is null then 1 else 0 end) as register,
sum(case when apd.objectstatuspulangfk = 13 and apd.objectruanganasalfk is not null then 1 else 0 end) as pulangksl,
sum(case when apd.objectstatuspulangfk = 15 and apd.objectruanganasalfk is not null then 1 else 0 end) as rawatksl,
sum(case when apd.objectstatuspulangfk = 14 and apd.objectruanganasalfk is not null then 1 else 0 end) as konsulplgksl,
sum(case when apd.objectstatuspulangfk = 16 and apd.objectruanganasalfk is not null then 1 else 0 end) as rujukksl,
sum(case when pd.statusenabled = 0 then 1 else 0 end) as batalksl,
sum(case when apd.objectstatuspulangfk not in (13,15,14,16) or apd.objectruanganasalfk is not null then 1 else 0 end) as registerksl,

case when ru1.objectdepartemenfk = 16 then ru.namaruangan + ' Rawat Inap'
when ru1.objectdepartemenfk = 18 then ru.namaruangan + ' Rawat Jalan'
when ru1.objectdepartemenfk = 24 then ru.namaruangan + ' Gawat Darurat'
when ru1.objectdepartemenfk = 28 then ru.namaruangan + ' Rehab Medik'
when ru1.objectdepartemenfk = 3 then ru.namaruangan + ' Laboratorium'
when ru1.objectdepartemenfk = 25 then ru.namaruangan + ' Bedah Sentral'
else ru.namaruangan end as namaruangan
from antrianpasiendiperiksa_t as apd
inner join pasiendaftar_t as pd on apd.noregistrasifk = pd.norec
inner join pasien_m as ps on pd.nocmfk = ps.id
inner join ruangan_m as ru on apd.objectruanganfk = ru.id
left join ruangan_m as ru1 on apd.objectruanganasalfk = ru1.id
where apd.tglregistrasi between '$tglAwal' and '$tglAkhir'
$Ruangan $paramDept $paramRuangan and pd.statusenabled = 1 and apd.statusenabled = 1
group by apd.tglregistrasi, ru.id, ru.namaruangan,pd.noregistrasi, apd.objectruanganasalfk, ps.namapasien, ru1.objectdepartemenfk) as x
group by x.namaruangan, x.idruangan, x.iddepartemen
        "));

        $datafix = [];
        foreach ($data as $item)
            $datafix[] = array(
                'iddepartemen' => $item->iddepartemen,
                'idruangan' => $item->idruangan,
                'namaruangan' => $item->namaruangan,
                'jmlPasienBaru' => (float)$item->jmlPasienBaru,
                'jmlPasienLama' => (float)$item->jmlPasienLama,
                'jmlPasien' => (float)$item->jmlPasien,
                'jmlPasienTracer' => (float)$item->jmlPasienTracer,
                'jmlPasienNonTracer' => (float)$item->jmlPasienNonTracer,
                'jmlPasienKonsul' => (float)$item->jmlPasienKonsul,
                'jmlPasienKunjungan' => (float)$item->jmlPasienKunjungan,
                'jmlPasienBpjsPol' => (float)$item->jmlPasienBpjsPol,
                'jmlPasienBpjsNonPol' => (float)$item->jmlPasienBpjsNonPol,
                'jmlPasienPTT' => (float)$item->jmlPasienPTT,
                'jmlPasienUmum' => (float)$item->jmlPasienUmum,
                'jmlPasienTagihan' => (float)$item->jmlPasienTagihan,
                'jmlPasienPembayaran' => (float)$item->jmlPasienPembayaran,
                'jmlPasienSendiri' => (float)$item->jmlPasienSendiri,
                'jmlPasienRujukan' => (float)$item->jmlPasienRujukan,
                'jmlPasienPasca' => (float)$item->jmlPasienPasca,
                'jmlPasienKedatangan' => (float)$item->jmlPasienKedatangan,
                'jmlPulangPengunjungRegister' => (float)$item->jmlPulangPengunjungRegister,
                'jmlPulangPengunjungPulang' => (float)$item->jmlPulangPengunjungPulang,
                'jmlPulangPengunjungRawat' => (float)$item->jmlPulangPengunjungRawat,
                'jmlPulangPengunjungKonsul' => (float)$item->jmlPulangPengunjungKonsul,
                'jmlPulangPengunjungRujuk' => (float)$item->jmlPulangPengunjungRujuk,
                'jmlPulangPengunjungBatal' => (float)$item->jmlPulangPengunjungBatal,
                'jmlPulangPengunjung' => (float)$item->jmlPulangPengunjung,
                'jmlPulangKonsulRegister' => (float)$item->jmlPulangKonsulRegister,
                'jmlPulangKonsulPulang' => (float)$item->jmlPulangKonsulPulang,
                'jmlPulangKonsulRawat' => (float)$item->jmlPulangKonsulRawat,
                'jmlPulangKonsulKonsul' => (float)$item->jmlPulangKonsulKonsul,
                'jmlPulangKonsulRujuk' => (float)$item->jmlPulangKonsulRujuk,
                'jmlPulangKonsulBatal' => (float)$item->jmlPulangKonsulBatal,
                'jmlPulangKonsul' => (float)$item->jmlPulangKonsul,
                'TotalPulang' => (float)$item->TotalPulang,
                'TotalRegister' => (float)$item->TotalRegister,
                'TotalRawat' => (float)$item->TotalRawat,
                'TotalKonsul' => (float)$item->TotalKonsul,
                'TotalRujuk' => (float)$item->TotalRujuk,
                'TotalBatal' => (float)$item->TotalBatal,
                'TotalAll' => (float)$item->TotalAll
            );
        return $this->respond($datafix);
    }

