        // return ($isRI);
        // die();

        if ($isRI != true) {
            $data = \DB::table('antrianpasiendiperiksa_t as apd')
                ->leftjoin('pasiendaftar_t as pd', 'pd.norec', '=', 'apd.noregistrasifk')
                ->leftjoin('rekanan_m as rk', 'rk.id', '=', 'pd.objectrekananfk')
                ->leftjoin('ruangan_m as ru', 'ru.id', '=', 'apd.objectruanganfk')
                ->leftjoin('ruangan_m as ru2', 'ru2.id', '=', 'pd.objectruanganlastfk')
                ->leftjoin('departemen_m as dp', 'dp.id', '=', 'ru2.objectdepartemenfk')
                ->leftjoin('pasien_m as ps', 'ps.id', '=', 'pd.nocmfk')
                ->select(DB::raw('ROW_NUMBER() OVER (ORDER BY ru.namaruangan) AS nomor,ru.id as idruangan, pd.noregistrasi,
                        ru.namaruangan,apd.statuskunjungan,apd.objectruanganasalfk,pd.objectrekananfk,apd.objectasalrujukanfk,
                        apd.objectstatuspulangfk,pd.statusenabled,apd.statusenabled as batalkonsul,pd.objectjaminankhusus,pd.objectkelompokpasienlastfk'))
                ->whereNull('apd.objectruanganasalfk')
